window.AUTH=window.AUTH||{};window.AUTH["10-5400"]={"d":"10-5400","id":"2010/10-5400","n":"Tapia v. United States","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the United States supporting vacatur","date":"","url":"https://www.justice.gov/osg/media/198166/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/tapia-v-united-states-brief-merits","n":79}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep564/usrep564319/usrep564319.pdf","tr":true,"items":[{"t":"case","label":"Johnson v. United States","cite":"520 U.S. 461","y":1997,"id":"1996/96-203","sc":1,"sum":"The Court held that the trial court's action in this case was not \"plain error\" of the sort which an appellate court may notice under Federal Rule of Criminal Procedure 52(b).","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Kucana v. Holder","cite":"130 S. Ct. 827","y":2010,"id":"2009/08-911","sc":1,"sum":"The Court held that 8 U.S.C. Section 1252(a)(2)(B)(ii) does not preclude federal courts from hearing cases specified by the Attorney General, only cases that are specified by statute.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"op":5,"sum":"The Court found the Act to be valid because although Congress cannot generally delegate its legislative power to another Branch, the nondelegation doctrine does not prevent Congress from obtaining assistance from coordinate Branches.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Nken v. Holder","cite":"129 S. Ct. 1749","y":2009,"id":"2008/08-681","sc":1,"sum":"The Court held that a court of appeals' decision to stay an alien's removal pending consideration of the alien's petition for review is governed by the 4-factor traditional test.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"United States v. Anderson","cite":"15 F.3d 278","y":1994,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/15/278/","sum":"Stating that, under Section 3582(a), “a court may not ‘imprison[] as a means of promoting rehabilitation’ or serving medical needs”.","sumSrc":"brief:0","by":{"0":"14, 19"}},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"sum":"The Court held that the Sentencing Guidelines, where they allow judges to enhance sentences using facts not reviewed by juries, violated the Sixth Amendment right to trial by jury. The sentences of Booker and Fanfan, based partly on facts determined only by judges, were therefore unconstitutional.","sumSrc":"Oyez","by":{"0":"20, 21"}},{"t":"case","label":"United States v. Doe","cite":"617 F.3d 766","y":2010,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/617/766/","by":{"0":"25"}},{"t":"case","label":"United States v. Duran","cite":"37 F.3d 557","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/37/557/","op":4,"by":{"0":"passim"}},{"t":"case","label":"United States v. Giddings","cite":"37 F.3d 1091","y":1994,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/37/1091/","by":{"0":"14, 19, 39, 41"}},{"t":"case","label":"United States v. Harris","cite":"990 F.2d 594","y":1993,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/990/594/","sum":"Interpreting Section 994(k) as a “prohibition” on imprisoning or extending the term of imprisonment.","sumSrc":"brief:0","by":{"0":"21, 25"}},{"t":"case","label":"United States v. Hawk Wing","cite":"433 F.3d 622","y":2006,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/433/622/","op":1,"by":{"0":"14, 19, 39, 41"}},{"t":"case","label":"United States v. Higdon","cite":"531 F.3d 561","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/531/561/","by":{"0":"14"}},{"t":"case","label":"United States v. Hoffa","cite":"587 F.3d 610","y":2009,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/587/610/","by":{"0":"26"}},{"t":"case","label":"United States v. Jackson","cite":"70 F.3d 874","y":1995,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/70/874/","by":{"0":"26, 30, 39"}},{"t":"case","label":"United States v. Jimenez","cite":"605 F.3d 415","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/605/415/","op":1,"sum":"Explaining that the court has “construed § 3582(a) as barring the sentencing court from choosing prison, rather than a non-incarceration sentence, to promote rehabilitation”.","sumSrc":"brief:0","by":{"0":"14, 19, 25, 41"}},{"t":"case","label":"United States v. Kapaev","cite":"199 F.3d 596","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/199/596/","sum":"Holding that Section 994(l)(2) does not “prohibit all consecutive sentences for conspiracy and the substantive crime that was the object of the conspiracy”.","sumSrc":"brief:0","by":{"0":"23"}},{"t":"case","label":"United States v. Maier","cite":"975 F.2d 944","y":1992,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/975/944/","by":{"0":"24, 30, 40"}},{"t":"case","label":"United States v. Manzella","cite":"475 F.3d 152","y":2007,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/475/152/","op":1,"sum":"Holding that Section 3582(a) provides that a “defendant not be sent to prison or held there for a specific length of time for the sole purpose of rehabilitation”.","sumSrc":"brief:0","by":{"0":"passim"}},{"t":"case","label":"United States v. Marcus","cite":"130 S. Ct. 2159","y":2010,"id":"2009/08-1341","sc":1,"op":1,"sum":"The Court held that an appellate court may correct an error not raised at trial only when the appellant demonstrates that: (1) there is an error; (2) the error is clear and obvious; (3) the error affected the appellant's substantial rights; and (4) the error seriously affects the fairness, integrity, or public reputation of judicial proceedings.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"United States v. Melendez","cite":"279 F.3d 16","y":2002,"url":"https://www.courtlistener.com/c/F.3d/279/16/","by":{"0":"30"}},{"t":"case","label":"United States v. Mogel","cite":"956 F.2d 1555","y":1992,"url":"https://www.courtlistener.com/c/F.2d/956/1555/","by":{"0":"21, 23"}},{"t":"case","label":"United States v. Olano","cite":"507 U.S. 725","y":1993,"id":"1992/91-1306","sc":1,"op":1,"sum":"The presence of the alternate jurors during jury deliberations was not an error that the Court of Appeals was authorized to correct under Rule 52(b).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"United States v. Saccoccia","cite":"58 F.3d 754","y":1995,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/58/754/","by":{"0":"23"}},{"t":"case","label":"United States v. Tobacco","cite":"428 F.3d 1148","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/428/1148/","by":{"0":"26"}},{"t":"case","label":"United States v. Tsosie","cite":"376 F.3d 1210","y":2004,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/376/1210/","by":{"0":"25"}},{"t":"case","label":"United States v. Watson","cite":"482 F.3d 269","y":2007,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/482/269/","by":{"0":"25, 26"}},{"t":"case","label":"United States v. Williams","cite":"65 F.3d 301","y":1995,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/65/301/","by":{"0":"30"}},{"t":"case","label":"United States v. Wilson","cite":"503 U.S. 329","y":1992,"id":"1991/90-1745","sc":1,"sum":"It is the Attorney General who computes the amount of the § 3585(b) credit after the defendant has begun to serve his sentence.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"0":"20"}},{"t":"usc","label":"18 U.S.C. § 3551","url":"https://www.law.cornell.edu/uscode/text/18/3551","subs":["(a)","(b)"],"by":{"0":"2, 16, 11, 14, 15"}},{"t":"usc","label":"28 U.S.C. § 991","url":"https://www.law.cornell.edu/uscode/text/28/991","by":{"0":"2"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)","(a)(1)","(a)(2)","(a)(2)(D)","(a)(3)","(a)(4)","(a)(5)","(a)(6)","(a)(7)"],"by":{"0":"2, 3, 6, 9, 15, 24, 16, 2, 16, passim, 16, 16, 16, 16, 16"}},{"t":"usc","label":"18 U.S.C. § 3554","url":"https://www.law.cornell.edu/uscode/text/18/3554","by":{"0":"15"}},{"t":"usc","label":"18 U.S.C. § 3555","url":"https://www.law.cornell.edu/uscode/text/18/3555","by":{"0":"15"}},{"t":"usc","label":"18 U.S.C. § 3556","url":"https://www.law.cornell.edu/uscode/text/18/3556","by":{"0":"15"}},{"t":"usc","label":"18 U.S.C. § 3562","url":"https://www.law.cornell.edu/uscode/text/18/3562","subs":["(a)"],"stext":{"head":"§3562. Imposition of a sentence of probation","paras":[[0,"(a) Factors To Be Considered in Imposing a Term of Probation.—The court, in determining whether to impose a term of probation, and, if a term of probation is to be imposed, in determining the length of the term and the conditions of probation, shall consider the factors set forth in section 3553(a) to the extent that they are applicable."],[0,"(b) Effect of Finality of Judgment.—Notwithstanding the fact that a sentence of probation can subsequently be—"],[1,"(1) modified or revoked pursuant to the provisions of section 3564 or 3565;"],[1,"(2) corrected pursuant to the provisions of rule 35 of the Federal Rules of Criminal Procedure and section 3742; or"],[1,"(3) appealed and modified, if outside the guideline range, pursuant to the provisions of section 3742;"],[0,"a judgment of conviction that includes such a sentence constitutes a final judgment for all other purposes."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3562?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3562. Imposition of a sentence of probation","tname":"Crimes and Criminal Procedure","by":{"0":"11, 3, 24"}},{"t":"usc","label":"18 U.S.C. § 3563","url":"https://www.law.cornell.edu/uscode/text/18/3563","subs":["(a)(4)","(b)(9)","(b)(11)"],"by":{"0":"11, 25, 25, 26, 26"}},{"t":"usc","label":"18 U.S.C. § 3572","url":"https://www.law.cornell.edu/uscode/text/18/3572","subs":["(a)"],"by":{"0":"3, 24"}},{"t":"usc","label":"18 U.S.C. § 3582","url":"https://www.law.cornell.edu/uscode/text/18/3582","subs":["(a)"],"stext":{"head":"§3582. Imposition of a sentence of imprisonment","paras":[[0,"(a) Factors To Be Considered in Imposing a Term of Imprisonment.—The court, in determining whether to impose a term of imprisonment, and, if a term of imprisonment is to be imposed, in determining the length of the term, shall consider the factors set forth in section 3553(a) to the extent that they are applicable, recognizing that imprisonment is not an appropriate means of promoting correction and rehabilitation. In determining whether to make a recommendation concerning the type of prison facility appropriate for the defendant, the court shall consider any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a)(2)."],[0,"(b) Effect of Finality of Judgment.—Notwithstanding the fact that a sentence to imprisonment can subsequently be—"],[1,"(1) modified pursuant to the provisions of subsection (c);"],[1,"(2) corrected pursuant to the provisions of rule 35 of the Federal Rules of Criminal Procedure and section 3742; or"],[1,"(3) appealed and modified, if outside the guideline range, pursuant to the provisions of section 3742;"],[0,"a judgment of conviction that includes such a sentence constitutes a final judgment for all other purposes."],[0,"(c) Modification of an Imposed Term of Imprisonment.—The court may not modify a term of imprisonment once it has been imposed except that—"],[1,"(1) in any case—"],[2,"(A) the court, upon motion of the Director of the Bureau of Prisons, or upon motion of the defendant after the defendant has fully exhausted all administrative rights to appeal a failure of the Bureau of Prisons to bring a motion on the defendant's behalf or the lapse of 30 days from the receipt of such a request by the warden of the defendant's facility, whichever is earlier, may reduce the term of imprisonment (and may impose a term of probation or supervised release with or without conditions that does not exceed the unserved portion of the original term of imprisonment), after considering the factors set forth in section 3553(a) to the extent that they are applicable, if it finds that—"],[3,"(i) extraordinary and compelling reasons warrant such a reduction; or"],[3,"(ii) the defendant is at least 70 years of age, has served at least 30 years in prison, pursuant to a sentence imposed under section 3559(c), for the offense or offenses for which the defendant is currently imprisoned, and a determination has been made by the Director of the Bureau of Prisons that the defendant is not a danger to the safety of any other person or the community, as provided under section 3142(g);"],[2,"and that such a reduction is consistent with applicable policy statements issued by the Sentencing Commission; and"],[2,"(B) the court may modify an imposed term of imprisonment to the extent otherwise expressly permitted by statute or by Rule 35 of the Federal Rules of Criminal Procedure; and"],[1,"(2) in the case of a defendant who has been sentenced to a term of imprisonment based on a sentencing range that has subsequently been lowered by the Sentencing Commission pursuant to 28 U.S.C. 994(o), upon motion of the defendant or the Director of the Bureau of Prisons, or on its own motion, the court may reduce the term of imprisonment, after considering the factors set forth in section 3553(a) to the extent that they are applicable, if such a reduction is consistent with applicable policy statements issued by the Sentencing Commission."],[0,"(d) Notification Requirements.—"],[1,"(1) Terminal illness defined.—In this subsection, the term \"terminal illness\" means a disease or condition with an end-of-life trajectory."],[1,"(2) Notification.—The Bureau of Prisons shall, subject to any applicable confidentiality requirements—"],[2,"(A) in the case of a defendant diagnosed with a terminal illness—"],[3,"(i) not later than 72 hours after the diagnosis notify the defendant's attorney, partner, and family members of the defendant's condition and inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) not later than 7 days after the date of the diagnosis, provide the defendant's partner and family members (including extended family) with an opportunity to visit the defendant in person;"],[3,"(iii) upon request from the defendant or his attorney, partner, or a family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[3,"(iv) not later than 14 days of receipt of a request for a sentence reduction submitted on the defendant's behalf by the defendant or the defendant's attorney, partner, or family member, process the request;"],[2,"(B) in the case of a defendant who is physically or mentally unable to submit a request for a sentence reduction pursuant to subsection (c)(1)(A)—"],[3,"(i) inform the defendant's attorney, partner, and family members that they may prepare and submit on the defendant's behalf a request for a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) accept and process a request for sentence reduction that has been prepared and submitted on the defendant's behalf by the defendant's attorney, partner, or family member under clause (i); and"],[3,"(iii) upon request from the defendant or his attorney, partner, or family member, ensure that Bureau of Prisons employees assist the defendant in the preparation, drafting, and submission of a request for a sentence reduction pursuant to subsection (c)(1)(A); and"],[2,"(C) ensure that all Bureau of Prisons facilities regularly and visibly post, including in prisoner handbooks, staff training materials, and facility law libraries and medical and hospice facilities, and make available to prisoners upon demand, notice of—"],[3,"(i) a defendant's ability to request a sentence reduction pursuant to subsection (c)(1)(A);"],[3,"(ii) the procedures and timelines for initiating and resolving requests described in clause (i); and"],[3,"(iii) the right to appeal a denial of a request described in clause (i) after all administrative rights to appeal within the Bureau of Prisons have been exhausted."],[1,"(3) Annual report.—Not later than 1 year after December 21, 2018, and once every year thereafter, the Director of the Bureau of Prisons shall submit to the Committee on the Judiciary of the Senate and the Committee on the Judiciary of the House of Representatives a report on requests for sentence reductions pursuant to subsection (c)(1)(A), which shall include a description of, for the previous year—"],[2,"(A) the number of prisoners granted and denied sentence reductions, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(B) the number of requests initiated by or on behalf of prisoners, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(C) the number of requests that Bureau of Prisons employees assisted prisoners in drafting, preparing, or submitting, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(D) the number of requests that attorneys, partners, or family members submitted on a defendant's behalf, categorized by the criteria relied on as the grounds for a reduction in sentence, and the final decision made in each request;"],[2,"(E) the number of requests approved by the Director of the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(F) the number of requests denied by the Director of the Bureau of Prisons and the reasons given for each denial, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(G) for each request, the time elapsed between the date the request was received by the warden and the final decision, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(H) for each request, the number of prisoners who died while their request was pending and, for each, the amount of time that had elapsed between the date the request was received by the Bureau of Prisons, categorized by the criteria relied on as the grounds for a reduction in sentence;"],[2,"(I) the number of Bureau of Prisons notifications to attorneys, partners, and family members of their right to visit a terminally ill defendant as required under paragraph (2)(A)(ii) and, for each, whether a visit occurred and how much time elapsed between the notification and the visit;"],[2,"(J) the number of visits to terminally ill prisoners that were denied by the Bureau of Prisons due to security or other concerns, and the reasons given for each denial; and"],[2,"(K) the number of motions filed by defendants with the court after all administrative rights to appeal a denial of a sentence reduction had been exhausted, the outcome of each motion, and the time that had elapsed between the date the request was first received by the Bureau of Prisons and the date the defendant filed the motion with the court."],[0,"(e) Inclusion of an Order To Limit Criminal Association of Organized Crime and Drug Offenders.—The court, in imposing a sentence to a term of imprisonment upon a defendant convicted of a felony set forth in chapter 95 (racketeering) or 96 (racketeer influenced and corrupt organizations) of this title or in the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 801 et seq.), or at any time thereafter upon motion by the Director of the Bureau of Prisons or a United States attorney, may include as a part of the sentence an order that requires that the defendant not associate or communicate with a specified person, other than his attorney, upon a showing of probable cause to believe that association or communication with such person is for the purpose of enabling the defendant to control, manage, direct, finance, or otherwise participate in an illegal enterprise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3582?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§3582. Imposition of a sentence of imprisonment","tname":"Crimes and Criminal Procedure","by":{"0":"passim"}},{"t":"usc","label":"18 U.S.C. § 3583","url":"https://www.law.cornell.edu/uscode/text/18/3583","subs":["(a)","(c)","(d)","(e)(3)"],"stext":{"head":"§3583. Inclusion of a term of supervised release after imprisonment","paras":[[0,"(a) In General.—The court, in imposing a sentence to a term of imprisonment for a felony or a misdemeanor, may include as a part of the sentence a requirement that the defendant be placed on a term of supervised release after imprisonment, except that the court shall include as a part of the sentence a requirement that the defendant be placed on a term of supervised release if such a term is required by statute or if the defendant has been convicted for the first time of a domestic violence crime as defined in section 3561(b)."],[0,"(b) Authorized Terms of Supervised Release.—Except as otherwise provided, the authorized terms of supervised release are—"],[1,"(1) for a Class A or Class B felony, not more than five years;"],[1,"(2) for a Class C or Class D felony, not more than three years; and"],[1,"(3) for a Class E felony, or for a misdemeanor (other than a petty offense), not more than one year."],[0,"(c) Factors To Be Considered in Including a Term of Supervised Release.—The court, in determining whether to include a term of supervised release, and, if a term of supervised release is to be included, in determining the length of the term and the conditions of supervised release, shall consider the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)."],[0,"(d) Conditions of Supervised Release.—The court shall order, as an explicit condition of supervised release, that the defendant not commit another Federal, State, or local crime during the term of supervision, that the defendant make restitution in accordance with sections 3663 and 3663A, or any other statute authorizing a sentence of restitution, and that the defendant not unlawfully possess a controlled substance. The court shall order as an explicit condition of supervised release for a defendant convicted for the first time of a domestic violence crime as defined in section 3561(b) that the defendant attend a public, private, or private nonprofit offender rehabilitation program that has been approved by the court, in consultation with a State Coalition Against Domestic Violence or other appropriate experts, if an approved program is readily available within a 50-mile radius of the legal residence of the defendant. The court shall order, as an explicit condition of supervised release for a person required to register under the Sex Offender Registration and Notification Act, that the person comply with the requirements of that Act. The court shall order, as an explicit condition of supervised release, that the defendant cooperate in the collection of a DNA sample from the defendant, if the collection of such a sample is authorized pursuant to section 3 of the DNA Analysis Backlog Elimination Act of 2000. The court shall also order, as an explicit condition of supervised release, that the defendant refrain from any unlawful use of a controlled substance and submit to a drug test within 15 days of release on supervised release and at least 2 periodic drug tests thereafter (as determined by the court) for use of a controlled substance. The condition stated in the preceding sentence may be ameliorated or suspended by the court as provided in section 3563(a)(4).1 The results of a drug test administered in accordance with the preceding subsection shall be subject to confirmation only if the results are positive, the defendant is subject to possible imprisonment for such failure, and either the defendant denies the accuracy of such test or there is some other reason to question the results of the test. A drug test confirmation shall be a urine drug test confirmed using gas chromatography/mass spectrometry techniques or such test as the Director of the Administrative Office of the United States Courts after consultation with the Secretary of Health and Human Services may determine to be of equivalent accuracy. The court shall consider whether the availability of appropriate substance abuse treatment programs, or an individual's current or past participation in such programs, warrants an exception in accordance with United States Sentencing Commission guidelines from the rule of section 3583(g) when considering any action against a defendant who fails a drug test. The court may order, as a further condition of supervised release, to the extent that such condition—"],[1,"(1) is reasonably related to the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), and (a)(2)(D);"],[1,"(2) involves no greater deprivation of liberty than is reasonably necessary for the purposes set forth in section 3553(a)(2)(B), (a)(2)(C), and (a)(2)(D); and"],[1,"(3) is consistent with any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a);"],[0,"any condition set forth as a discretionary condition of probation in section 3563(b) and any other condition it considers to be appropriate, provided, however that a condition set forth in subsection 3563(b)(10) shall be imposed only for a violation of a condition of supervised release in accordance with section 3583(e)(2) and only when facilities are available. If an alien defendant is subject to deportation, the court may provide, as a condition of supervised release, that he be deported and remain outside the United States, and may order that he be delivered to a duly authorized immigration official for such deportation. The court may order, as an explicit condition of supervised release for a person who is a felon and required to register under the Sex Offender Registration and Notification Act, that the person submit his person, and any property, house, residence, vehicle, papers, computer, other electronic communications or data storage devices or media, and effects to search at any time, with or without a warrant, by any law enforcement or probation officer with reasonable suspicion concerning a violation of a condition of supervised release or unlawful conduct by the person, and by any probation officer in the lawful discharge of the officer's supervision functions."],[0,"(e) Modification of Conditions or Revocation.—The court may, after considering the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)—"],[1,"(1) terminate a term of supervised release and discharge the defendant released at any time after the expiration of one year of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation, if it is satisfied that such action is warranted by the conduct of the defendant released and the interest of justice;"],[1,"(2) extend a term of supervised release if less than the maximum authorized term was previously imposed, and may modify, reduce, or enlarge the conditions of supervised release, at any time prior to the expiration or termination of the term of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation and the provisions applicable to the initial setting of the terms and conditions of post-release supervision;"],[1,"(3) revoke a term of supervised release, and require the defendant to serve in prison all or part of the term of supervised release authorized by statute for the offense that resulted in such term of supervised release without credit for time previously served on postrelease supervision, if the court, pursuant to the Federal Rules of Criminal Procedure applicable to revocation of probation or supervised release, finds by a preponderance of the evidence that the defendant violated a condition of supervised release, except that a defendant whose term is revoked under this paragraph may not be required to serve on any such revocation more than 5 years in prison if the offense that resulted in the term of supervised release is a class A felony, more than 3 years in prison if such offense is a class B felony, more than 2 years in prison if such offense is a class C or D felony, or more than one year in any other case; or"],[1,"(4) order the defendant to remain at his place of residence during nonworking hours and, if the court so directs, to have compliance monitored by telephone or electronic signaling devices, except that an order under this paragraph may be imposed only as an alternative to incarceration."],[0,"(f) Written Statement of Conditions.—The court shall direct that the probation officer provide the defendant with a written statement that sets forth all the conditions to which the term of supervised release is subject, and that is sufficiently clear and specific to serve as a guide for the defendant's conduct and for such supervision as is required."],[0,"(g) Mandatory Revocation for Possession of Controlled Substance or Firearm or for Refusal To Comply With Drug Testing.—If the defendant—"],[1,"(1) possesses a controlled substance in violation of the condition set forth in subsection (d);"],[1,"(2) possesses a firearm, as such term is defined in section 921 of this title, in violation of Federal law, or otherwise violates a condition of supervised release prohibiting the defendant from possessing a firearm;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3583?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3583. Inclusion of a term of supervised release after imprisonment","tname":"Crimes and Criminal Procedure","by":{"0":"3, 11, 15, 24, 25, 25, 26, 25"}},{"t":"usc","label":"28 U.S.C. § 994","url":"https://www.law.cornell.edu/uscode/text/28/994","subs":["(a)","(a)(1)","(e)","(k)","(l)(1)","(l)(2)","(t)"],"stext":{"head":"§994. Duties of the Commission","paras":[[0,"(a) The Commission, by affirmative vote of at least four members of the Commission, and pursuant to its rules and regulations and consistent with all pertinent provisions of any Federal statute shall promulgate and distribute to all courts of the United States and to the United States Probation System—"],[1,"(1) guidelines, as described in this section, for use of a sentencing court in determining the sentence to be imposed in a criminal case, including—"],[2,"(A) a determination whether to impose a sentence to probation, a fine, or a term of imprisonment;"],[2,"(B) a determination as to the appropriate amount of a fine or the appropriate length of a term of probation or a term of imprisonment;"],[2,"(C) a determination whether a sentence to a term of imprisonment should include a requirement that the defendant be placed on a term of supervised release after imprisonment, and, if so, the appropriate length of such a term;"],[2,"(D) a determination whether multiple sentences to terms of imprisonment should be ordered to run concurrently or consecutively; and"],[2,"(E) a determination under paragraphs (6) and (11) 1 of section 3563(b) of title 18;"],[1,"(2) general policy statements regarding application of the guidelines or any other aspect of sentencing or sentence implementation that in the view of the Commission would further the purposes set forth in section 3553(a)(2) of title 18, United States Code, including the appropriate use of—"],[2,"(A) the sanctions set forth in sections 3554, 3555, and 3556 of title 18;"],[2,"(B) the conditions of probation and supervised release set forth in sections 3563(b) and 3583(d) of title 18;"],[2,"(C) the sentence modification provisions set forth in sections 3563(c), 3564, 3573, and 3582(c) of title 18;"],[2,"(D) the fine imposition provisions set forth in section 3572 of title 18;"],[2,"(E) the authority granted under rule 11(e)(2) of the Federal Rules of Criminal Procedure to accept or reject a plea agreement entered into pursuant to rule 11(e)(1); and"],[2,"(F) the temporary release provisions set forth in section 3622 of title 18, and the prerelease custody provisions set forth in section 3624(c) of title 18; and"],[1,"(3) guidelines or general policy statements regarding the appropriate use of the provisions for revocation of probation set forth in section 3565 of title 18, and the provisions for modification of the term or conditions of supervised release and revocation of supervised release set forth in section 3583(e) of title 18."],[0,"(b)(1) The Commission, in the guidelines promulgated pursuant to subsection (a)(1), shall, for each category of offense involving each category of defendant, establish a sentencing range that is consistent with all pertinent provisions of title 18, United States Code."],[0,"(2) If a sentence specified by the guidelines includes a term of imprisonment, the maximum of the range established for such a term shall not exceed the minimum of that range by more than the greater of 25 percent or 6 months, except that, if the minimum term of the range is 30 years or more, the maximum may be life imprisonment."],[0,"(c) The Commission, in establishing categories of offenses for use in the guidelines and policy statements governing the imposition of sentences of probation, a fine, or imprisonment, governing the imposition of other authorized sanctions, governing the size of a fine or the length of a term of probation, imprisonment, or supervised release, and governing the conditions of probation, supervised release, or imprisonment, shall consider whether the following matters, among others, have any relevance to the nature, extent, place of service, or other incidents 2 of an appropriate sentence, and shall take them into account only to the extent that they do have relevance—"],[1,"(1) the grade of the offense;"],[1,"(2) the circumstances under which the offense was committed which mitigate or aggravate the seriousness of the offense;"],[1,"(3) the nature and degree of the harm caused by the offense, including whether it involved property, irreplaceable property, a person, a number of persons, or a breach of public trust;"],[1,"(4) the community view of the gravity of the offense;"],[1,"(5) the public concern generated by the offense;"],[1,"(6) the deterrent effect a particular sentence may have on the commission of the offense by others; and"],[1,"(7) the current incidence of the offense in the community and in the Nation as a whole."],[0,"(d) The Commission in establishing categories of defendants for use in the guidelines and policy statements governing the imposition of sentences of probation, a fine, or imprisonment, governing the imposition of other authorized sanctions, governing the size of a fine or the length of a term of probation, imprisonment, or supervised release, and governing the conditions of probation, supervised release, or imprisonment, shall consider whether the following matters, among others, with respect to a defendant, have any relevance to the nature, extent, place of service, or other incidents 2 of an appropriate sentence, and shall take them into account only to the extent that they do have relevance—"],[1,"(1) age;"],[1,"(2) education;"],[1,"(3) vocational skills;"],[1,"(4) mental and emotional condition to the extent that such condition mitigates the defendant's culpability or to the extent that such condition is otherwise plainly relevant;"],[1,"(5) physical condition, including drug dependence;"],[1,"(6) previous employment record;"],[1,"(7) family ties and responsibilities;"],[1,"(8) community ties;"],[1,"(9) role in the offense;"],[1,"(10) criminal history; and"],[1,"(11) degree of dependence upon criminal activity for a livelihood."],[0,"The Commission shall assure that the guidelines and policy statements are entirely neutral as to the race, sex, national origin, creed, and socioeconomic status of offenders."],[0,"(e) The Commission shall assure that the guidelines and policy statements, in recommending a term of imprisonment or length of a term of imprisonment, reflect the general inappropriateness of considering the education, vocational skills, employment record, family ties and responsibilities, and community ties of the defendant."],[0,"(f) The Commission, in promulgating guidelines pursuant to subsection (a)(1), shall promote the purposes set forth in section 991(b)(1), with particular attention to the requirements of subsection 991(b)(1)(B) for providing certainty and fairness in sentencing and reducing unwarranted sentence disparities."],[0,"(g) The Commission, in promulgating guidelines pursuant to subsection (a)(1) to meet the purposes of sentencing as set forth in section 3553(a)(2) of title 18, United States Code, shall take into account the nature and capacity of the penal, correctional, and other facilities and services available, and shall make recommendations concerning any change or expansion in the nature or capacity of such facilities and services that might become necessary as a result of the guidelines promulgated pursuant to the provisions of this chapter. The sentencing guidelines prescribed under this chapter shall be formulated to minimize the likelihood that the Federal prison population will exceed the capacity of the Federal prisons, as determined by the Commission."],[0,"(h) The Commission shall assure that the guidelines specify a sentence to a term of imprisonment at or near the maximum term authorized for categories of defendants in which the defendant is eighteen years old or older and—"],[1,"(1) has been convicted of a felony that is—"],[2,"(A) a crime of violence; or"],[2,"(B) an offense described in section 401 of the Controlled Substances Act (21 U.S.C. 841), sections 1002(a), 1005, and 1009 of the Controlled Substances Import and Export Act (21 U.S.C. 952(a), 955, and 959), and chapter 705 of title 46; and"],[1,"(2) has previously been convicted of two or more prior felonies, each of which is—"],[2,"(A) a crime of violence; or"],[2,"(B) an offense described in section 401 of the Controlled Substances Act (21 U.S.C. 841), sections 1002(a), 1005, and 1009 of the Controlled Substances Import and Export Act (21 U.S.C. 952(a), 955, and 959), and chapter 705 of title 46."],[0,"(i) The Commission shall assure that the guidelines specify a sentence to a substantial term of imprisonment for categories of defendants in which the defendant—"],[1,"(1) has a history of two or more prior Federal, State, or local felony convictions for offenses committed on different occasions;"],[1,"(2) committed the offense as part of a pattern of criminal conduct from which the defendant derived a substantial portion of the defendant's income;"],[1,"(3) committed the offense in furtherance of a conspiracy with three or more persons engaging in a pattern of racketeering activity in which the defendant participated in a managerial or supervisory capacity;"],[1,"(4) committed a crime of violence that constitutes a felony while on release pending trial, sentence, or appeal from a Federal, State, or local felony for which he was ultimately convicted; or"],[1,"(5) committed a felony that is set forth in section 401 or 1010 of the Comprehensive Drug Abuse Prevention and Control Act of 1970 (21 U.S.C. 841 and 960), and that involved trafficking in a substantial quantity of a controlled substance."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/994?type=usc&year=mostrecent&link-type=html"},"op":4,"ar":1,"head":"§994. Duties of the Commission","tname":"Judiciary and Judicial Procedure","by":{"0":"20, 23, 20, 3, 22, 36, 31, 32, 33, 34, passim, 22, 22, 23, 36"}},{"t":"usc","label":"8 U.S.C. § 1324","url":"https://www.law.cornell.edu/uscode/text/8/1324","subs":["(a)(2)(B)(ii)","(a)(2)(B)(iii)"],"stext":{"head":"§1324. Bringing in and harboring certain aliens","paras":[[0,"(a) Criminal penalties"],[0,"(1)(A) Any person who—"],[1,"(i) knowing that a person is an alien, brings to or attempts to bring to the United States in any manner whatsoever such person at a place other than a designated port of entry or place other than as designated by the Commissioner, regardless of whether such alien has received prior official authorization to come to, enter, or reside in the United States and regardless of any future official action which may be taken with respect to such alien;"],[1,"(ii) knowing or in reckless disregard of the fact that an alien has come to, entered, or remains in the United States in violation of law, transports, or moves or attempts to transport or move such alien within the United States by means of transportation or otherwise, in furtherance of such violation of law;"],[1,"(iii) knowing or in reckless disregard of the fact that an alien has come to, entered, or remains in the United States in violation of law, conceals, harbors, or shields from detection, or attempts to conceal, harbor, or shield from detection, such alien in any place, including any building or any means of transportation;"],[1,"(iv) encourages or induces an alien to come to, enter, or reside in the United States, knowing or in reckless disregard of the fact that such coming to, entry, or residence is or will be in violation of law; or"],[1,"(v)(I) engages in any conspiracy to commit any of the preceding acts, or"],[1,"(II) aids or abets the commission of any of the preceding acts,"],[0,"shall be punished as provided in subparagraph (B)."],[0,"(B) A person who violates subparagraph (A) shall, for each alien in respect to whom such a violation occurs—"],[1,"(i) in the case of a violation of subparagraph (A)(i) or (v)(I) or in the case of a violation of subparagraph (A)(ii), (iii), or (iv) in which the offense was done for the purpose of commercial advantage or private financial gain, be fined under title 18, imprisoned not more than 10 years, or both;"],[1,"(ii) in the case of a violation of subparagraph (A)(ii), (iii), (iv), or (v)(II), be fined under title 18, imprisoned not more than 5 years, or both;"],[1,"(iii) in the case of a violation of subparagraph (A)(i), (ii), (iii), (iv), or (v) during and in relation to which the person causes serious bodily injury (as defined in section 1365 of title 18) to, or places in jeopardy the life of, any person, be fined under title 18, imprisoned not more than 20 years, or both; and"],[1,"(iv) in the case of a violation of subparagraph (A)(i), (ii), (iii), (iv), or (v) resulting in the death of any person, be punished by death or imprisoned for any term of years or for life, fined under title 18, or both."],[0,"(C) It is not a violation of clauses 1 (ii) or (iii) of subparagraph (A), or of clause (iv) of subparagraph (A) except where a person encourages or induces an alien to come to or enter the United States, for a religious denomination having a bona fide nonprofit, religious organization in the United States, or the agents or officers of such denomination or organization, to encourage, invite, call, allow, or enable an alien who is present in the United States to perform the vocation of a minister or missionary for the denomination or organization in the United States as a volunteer who is not compensated as an employee, notwithstanding the provision of room, board, travel, medical assistance, and other basic living expenses, provided the minister or missionary has been a member of the denomination for at least one year."],[0,"(2) Any person who, knowing or in reckless disregard of the fact that an alien has not received prior official authorization to come to, enter, or reside in the United States, brings to or attempts to bring to the United States in any manner whatsoever, such alien, regardless of any official action which may later be taken with respect to such alien shall, for each alien in respect to whom a violation of this paragraph occurs—"],[1,"(A) be fined in accordance with title 18 or imprisoned not more than one year, or both; or"],[1,"(B) in the case of—"],[2,"(i) an offense committed with the intent or with reason to believe that the alien unlawfully brought into the United States will commit an offense against the United States or any State punishable by imprisonment for more than 1 year,"],[2,"(ii) an offense done for the purpose of commercial advantage or private financial gain, or"],[2,"(iii) an offense in which the alien is not upon arrival immediately brought and presented to an appropriate immigration officer at a designated port of entry,"],[1,"be fined under title 18 and shall be imprisoned, in the case of a first or second violation of subparagraph (B)(iii), not more than 10 years, in the case of a first or second violation of subparagraph (B)(i) or (B)(ii), not less than 3 nor more than 10 years, and for any other violation, not less than 5 nor more than 15 years."],[0,"(3)(A) Any person who, during any 12-month period, knowingly hires for employment at least 10 individuals with actual knowledge that the individuals are aliens described in subparagraph (B) shall be fined under title 18 or imprisoned for not more than 5 years, or both."],[0,"(B) An alien described in this subparagraph is an alien who—"],[1,"(i) is an unauthorized alien (as defined in section 1324a(h)(3) of this title), and"],[1,"(ii) has been brought into the United States in violation of this subsection."],[0,"(4) In the case of a person who has brought aliens into the United States in violation of this subsection, the sentence otherwise provided for may be increased by up to 10 years if—"],[1,"(A) the offense was part of an ongoing commercial organization or enterprise;"],[1,"(B) aliens were transported in groups of 10 or more; and"],[1,"(C)(i) aliens were transported in a manner that endangered their lives; or"],[1,"(ii) the aliens presented a life-threatening health risk to people in the United States."],[0,"(b) Seizure and forfeiture"],[0,"(1) In general"],[1,"Any conveyance, including any vessel, vehicle, or aircraft, that has been or is being used in the commission of a violation of subsection (a), the gross proceeds of such violation, and any property traceable to such conveyance or proceeds, shall be seized and subject to forfeiture."],[0,"(2) Applicable procedures"],[1,"Seizures and forfeitures under this subsection shall be governed by the provisions of chapter 46 of title 18 relating to civil forfeitures, including section 981(d) of such title, except that such duties as are imposed upon the Secretary of the Treasury under the customs laws described in that section shall be performed by such officers, agents, and other persons as may be designated for that purpose by the Attorney General."],[0,"(3) Prima facie evidence in determinations of violations"],[1,"In determining whether a violation of subsection (a) has occurred, any of the following shall be prima facie evidence that an alien involved in the alleged violation had not received prior official authorization to come to, enter, or reside in the United States or that such alien had come to, entered, or remained in the United States in violation of law:"],[2,"(A) Records of any judicial or administrative proceeding in which that alien's status was an issue and in which it was determined that the alien had not received prior official authorization to come to, enter, or reside in the United States or that such alien had come to, entered, or remained in the United States in violation of law."],[2,"(B) Official records of the Service or of the Department of State showing that the alien had not received prior official authorization to come to, enter, or reside in the United States or that such alien had come to, entered, or remained in the United States in violation of law."],[2,"(C) Testimony, by an immigration officer having personal knowledge of the facts concerning that alien's status, that the alien had not received prior official authorization to come to, enter, or reside in the United States or that such alien had come to, entered, or remained in the United States in violation of law."],[0,"(c) Authority to arrest"],[0,"No officer or person shall have authority to make any arrests for a violation of any provision of this section except officers and employees of the Service designated by the Attorney General, either individually or as a member of a class, and all other officers whose duty it is to enforce criminal laws."],[0,"(d) Admissibility of videotaped witness testimony"],[0,"Notwithstanding any provision of the Federal Rules of Evidence, the videotaped (or otherwise audiovisually preserved) deposition of a witness to a violation of subsection (a) who has been deported or otherwise expelled from the United States, or is otherwise unable to testify, may be admitted into evidence in an action brought for that violation if the witness was available for cross examination and the deposition otherwise complies with the Federal Rules of Evidence."],[0,"(e) Outreach program"],[0,"The Secretary of Homeland Security, in consultation with the Attorney General and the Secretary of State, as appropriate, shall develop and implement an outreach program to educate the public in the United States and abroad about the penalties for bringing in and harboring aliens in violation of this section."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1324?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1324. Bringing in and harboring certain aliens","tname":"Aliens and Nationality","by":{"0":"2, 5, 2, 5"}},{"t":"usc","label":"18 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/18/101","subs":["(b)(4)"],"by":{"0":"31"}},{"t":"usc","label":"18 U.S.C. § 2302","url":"https://www.law.cornell.edu/uscode/text/18/2302","subs":["(a)"],"by":{"0":"33"}},{"t":"usc","label":"18 U.S.C. § 3146","url":"https://www.law.cornell.edu/uscode/text/18/3146","by":{"0":"2, 5, 22"}},{"t":"usc","label":"18 U.S.C. § 3621","url":"https://www.law.cornell.edu/uscode/text/18/3621","subs":["(a)","(b)","(e)","(f)"],"by":{"0":"29, 29, 26, 29, 27"}},{"t":"usc","label":"18 U.S.C. § 3624","url":"https://www.law.cornell.edu/uscode/text/18/3624","subs":["(f)"],"by":{"0":"27"}},{"t":"reg","label":"28 C.F.R. § 550.51","url":"https://www.ecfr.gov/current/title-28/section-550.51","subs":["(b)(1)(iii)"],"by":{"0":"26"}},{"t":"rule","label":"Fed. R. Crim. P. 52","url":"https://www.law.cornell.edu/rules/frcrmp/rule_52","subs":["(b)"],"by":{"0":"42"}}]};